void ETSChecker::CheckMultipleOverride(ir::AstNode *it)
{
    if (!it->IsMethodDefinition() || (it->AsMethodDefinition()->Kind() != ir::MethodDefinitionKind::METHOD)) {
        return;
    }
    auto md = it->AsMethodDefinition();
    auto ts_type = md->TsType();
    if (ts_type->IsTypeError()) {
        return;
    }
    auto signature = md->Function()->Signature();
    std::set<const checker::Signature *> overriddenSignatures;
    for (auto os : signature->OverridesSignatures()) {
        overriddenSignatures.insert(os);
    }
    // at this point, we have overloads set for this method
    for (auto overload : md->Overloads()) {
        auto overloadSignature = overload->TsType()->AsETSFunctionType()->FindSignature(overload->Function());
        bool multipleOverrideFound = false;
        for (auto overriddenSignature : overloadSignature->OverridesSignatures()) {
            if (overriddenSignatures.find(overriddenSignature) != overriddenSignatures.end()) {
                multipleOverrideFound = true;
                LogError(diagnostic::CANNOT_OVERRIDE,
                         {signature->Function()->Id()->Name(), signature, signature->Owner(),
                          overriddenSignature->Function()->Id()->Name(), overriddenSignature,
                          overriddenSignature->Owner(), "2 methods override a single method in a superclass"},
                         signature->Function()->Start());
                break;
            }
        }
        if (multipleOverrideFound) {
            break;
        } else {
            for (auto os : overloadSignature->OverridesSignatures()) {
                overriddenSignatures.insert(os);
            }
        }
    }
}

void ETSChecker::CheckClassElement(ir::ClassDefinition *classDef)
{
    for (auto *it : classDef->Body()) {
        if (!it->IsClassProperty()) {
            if (it->IsETSModule() && it->AsETSModule()->IsNamespace()) {
                ES2PANDA_ASSERT(IsAnyError());
                continue;
            }
        }
        it->Check(this);
        CheckMultipleOverride(it);
    }
}

void ETSChecker::CheckClassAnnotations(ir::ClassDefinition *classDef)
{
    CheckAnnotations(classDef);
    if (classDef->TypeParams() != nullptr) {
        for (auto *param : classDef->TypeParams()->Params()) {
            CheckAnnotations(param);
        }
    }
}

void ETSChecker::CheckInterfaceAnnotations(ir::TSInterfaceDeclaration *interfaceDecl)
{
    CheckAnnotations(interfaceDecl);
    if (interfaceDecl->TypeParams() != nullptr) {
        for (auto *param : interfaceDecl->TypeParams()->Params()) {
            CheckAnnotations(param);
        }
    }
}

